/*
 * A069759  Frobenius number of the numerical semigroup generated by
 *          consecutive hex numbers.
 * https://oeis.org/A069759
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  easy, nonn
 * Formula:   a(n) = 9*n^4 + 36*n^3 + 45*n^2 + 18*n – 1 (offset 1)
 * Range:     u8 n <= 1, u16 n <= 8, u32 n <= 146, u64 n <= 1000,
 *            u128 n <= 1000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

seq_t a(idx_t n)
{
    /* Convert index to the sequence type before any arithmetic. */
    seq_t N  = (seq_t)n;

    /* Compute successive powers of n.  All operations are performed
       in `seq_t` so the calculation is exact for the chosen build. */
    seq_t n2 = N * N;
    seq_t n3 = n2 * N;
    seq_t n4 = n3 * N;

    /* Evaluate the polynomial using explicit casts for the integer
       coefficients to guarantee that the multiplication is done in
       the type `seq_t`. */
    seq_t result =
        (seq_t)9  * n4
      + (seq_t)36 * n3
      + (seq_t)45 * n2
      + (seq_t)18 * N
      - (seq_t)1;

    return result;
}
